glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_uv0;
in vec4 a_color;
out vec2 v_uv0;
out vec4 v_color;
void main () {
  gl_Position = cc_matViewProj * vec4(a_position, 1);
  v_uv0 = a_uv0;
  v_color = a_color;
}

glsl3.frag:
precision highp float;
in vec2 v_uv0;
in vec4 v_color;
uniform sampler2D mainTexture;
layout(std140) uniform Properties {
  vec2 center;
  vec2 size;
  float width;
  float height;
  float round;
  float feather;
};
void main () {
  vec4 color = v_color;
  color *= texture(mainTexture, v_uv0);
  float x = v_uv0.x;
  float y = v_uv0.y;
  float ratio = size.x / size.y;
  float minX = center.x - (width / 2.0);
  float maxX = center.x + (width / 2.0);
  float minY = center.y - (height * ratio / 2.0);
  float maxY = center.y + (height * ratio / 2.0);
  if (x >= minX && x <= maxX && y >= minY && y <= maxY) {
    if (round == 0.0) discard;
    float roundY = round * ratio;
    vec2 vertex;
    if (x <= minX + round) {
      if (y <= minY + roundY) {
        vertex = vec2(minX + round, (minY + roundY) / ratio);
      } else if (y >= maxY - roundY) {
        vertex = vec2(minX + round, (maxY - roundY) / ratio);
      } else {
        vertex = vec2(minX + round, y / ratio);
      }
    } else if (x >= maxX - round) {
      if (y <= minY + roundY){
        vertex = vec2(maxX - round, (minY + roundY) / ratio);
      } else if (y >= maxY - roundY) {
        vertex = vec2(maxX - round, (maxY - roundY) / ratio);
      } else {
        vertex = vec2(maxX - round, y / ratio);
      }
    } else if (y <= minY + roundY) {
      vertex = vec2(x, (minY + roundY) / ratio);
    } else if (y >= maxY - roundY) {
      vertex = vec2(x, (maxY - roundY) / ratio);
    } else {
      discard;
    }
    float dis = distance(vec2(x, y / ratio), vertex);
    color.a = smoothstep(round - feather, round, dis) * color.a;
  }
  color.a *= v_color.a;
  gl_FragColor = color;
}

